<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import {Button,Cell,CellGroup,Slider,Stepper,Switch,Popup,Picker,Collapse,CollapseItem} from 'vant';
import 'vant/es/button/style';import 'vant/es/cell/style';import 'vant/es/cell-group/style';import 'vant/es/slider/style';import 'vant/es/stepper/style';import 'vant/es/switch/style';import 'vant/es/popup/style';import 'vant/es/picker/style';import 'vant/es/collapse/style';import 'vant/es/collapse-item/style';
const props=defineProps({controller:{type:Object,required:true}}),m=ref(props.controller.model),a=props.controller.actions,error=ref(''),opened=ref([]),picker=ref(null),sceneHost=ref();
const unsubscribe=props.controller.subscribe(value=>{m.value=value;});onBeforeUnmount(unsubscribe);
function run(name,...args){try{error.value='';const result=a[name](...args);if(result?.catch)result.catch(e=>{error.value=e.message;});}catch(e){error.value=e.message;}}
onMounted(()=>{if(m.value.kind==='sound')run('attach',sceneHost.value);});
const choices=computed(()=>picker.value==='chapter'?m.value.chapters.map(c=>({text:'第'+c.number+'章 · '+c.title,value:c.id})):(m.value.controls.find(c=>c.key===picker.value)?.options||[]).map(([value,text])=>({text,value})));
function confirm({selectedValues}){const key=picker.value;picker.value=null;run(key==='chapter'?'chapter':'change',...(key==='chapter'?[selectedValues[0]]:[key,selectedValues[0]]));}
function label(control){return control.options?.find(([v])=>String(v)===String(m.value.state[control.key]))?.[1]||'';}
// Isolate SVG definition ids from the retained, hidden legacy diagram.
const displaySvg=computed(()=>{let svg=m.value.svg;const ids=[...svg.matchAll(/\bid="([^"]+)"/g)].map(match=>match[1]);for(const id of ids)svg=svg.replaceAll('id="'+id+'"','id="student-physics-'+id+'"').replaceAll('url(#'+id+')','url(#student-physics-'+id+')');return m.value.kind==='explore'?svg.replace('viewBox="0 0 800 420"','viewBox="0 0 800 400"'):svg;});
const marker=computed(()=>{const p=m.value.propagation;if(!p)return [];return [{name:'空气基准',progress:p.air,color:'#98adbb',show:true},{name:'当前介质',progress:p.current,color:'#ff788c',show:!!p.speed}].map(v=>({...v,x:35+745*v.progress,y:65-Math.sin(2*Math.PI*3*v.progress)*props.controller.inspect().gain*43}));});
</script>
<template>
<main class="physics-labs" :data-kind="m.kind">
 <header class="top"><div><p class="eyebrow">{{m.kind==='sound'?'AETHERVIZ · SOUND LAB':'AETHERVIZ · PHYSICS EXPLORER'}}</p><h1>{{m.kind==='sound'?'声现象 · 听见振动':'动手，让物理看得见'}}</h1><p v-if="m.kind==='sound'">用耳朵比较，用波形观察，用实验找到原因。</p></div><nav class="top-actions"><Button tag="a" :href="m.backHref">← 回到本章微课</Button><Button @click="run('reset')">重置</Button><Button @click="run('random')">随机条件</Button><Button @click="run('fullscreen')">全屏</Button><Button @click="run('about',true)">关于</Button></nav></header>
 <p v-if="error" role="alert">{{error}}</p><p v-if="m.notice" role="status">{{m.notice}}</p>
 <div class="lab-layout" :class="{collapsed:m.collapsed}">
  <aside class="sidebar"><div class="directory-heading"><span>{{m.kind==='explore'?'选择上册章节':'声现象实验目录'}}</span><Button size="small" :aria-expanded="!m.collapsed" @click="run('sidebar')">{{m.collapsed?'展开目录':'收起目录'}}</Button></div><div v-show="!m.collapsed">
   <Button v-if="m.kind==='explore'" block @click="picker='chapter'">第{{m.chapter.number}}章 · {{m.chapter.title}}</Button>
   <div class="topics"><Button v-for="(entry,i) in m.kind==='explore'?m.chapter.nodes:m.modules" :key="entry.id" :aria-current="(m.current.id||m.mode)===entry.id?'page':undefined" :type="(m.current.id||m.mode)===entry.id?'primary':'default'" @click="run('select',entry.id)"><span>{{String(i+1).padStart(2,'0')}}</span><span><strong>{{entry.title}}</strong><small>{{entry.section}}</small></span></Button></div>
  </div></aside>
  <article class="lab">
   <header class="lab-heading"><div><h2>{{m.current.title}}</h2><p>{{m.tip}}</p></div><span class="tag">{{m.current.section}}</span></header>
   <section class="observation"><div class="scene-top"><strong>{{m.kind==='sound'?m.sceneRenderer:'教学交互模型'}}</strong><span>{{m.playing?'过程演示中':'调整条件，观察变化'}}</span></div><div v-show="m.kind!=='sound'||!m.scene3D" class="diagram" v-html="displaySvg"></div><div v-if="m.kind==='sound'" v-show="m.scene3D" ref="sceneHost" class="scene-host"/>
    <div class="actions" :data-note="m.note"><Button :disabled="!m.canPlay" type="primary" @click="run('play')">{{!m.canPlay?'拖动参数观察':m.playing?'暂停过程':'播放过程'}}</Button><Button @click="run('step')">单步观察</Button><Button v-if="m.kind==='explore'" @click="run('record')">记录本组</Button></div>

   </section>
   <section class="controls card" aria-label="实验条件"><div class="card-head"><h3>动手调一调</h3><small>先预测，再验证</small></div><p class="tip">{{m.tip}}</p><Button v-if="m.kind==='sound'&&m.mode==='source'" @click="run('hold')">{{m.state.sourceHeld?'松开声源，恢复振动':'按住声源，停止振动'}}</Button><div v-for="control in m.controls" :key="control.key" class="control"><template v-if="control.type==='range'"><div class="control-title"><label :id="'lab-control-'+control.key">{{control.label}}</label><div><Stepper :model-value="m.state[control.key]" :min="control.min" :max="control.max" :step="control.step" :decimal-length="control.step<.1?3:control.step<1?2:0" :aria-label="control.label" @update:model-value="run('change',control.key,$event)"/><span>{{control.unit}}</span></div></div><Slider :model-value="m.state[control.key]" :min="control.min" :max="control.max" :step="control.step" :aria-labelledby="'lab-control-'+control.key" @update:model-value="run('change',control.key,$event)"/></template><Button v-else-if="control.type==='select'" block @click="picker=control.key">{{control.label}}：{{label(control)}}</Button><label v-else class="toggle">{{control.label}}<Switch :model-value="m.state[control.key]" :aria-label="control.label" @update:model-value="run('change',control.key,$event)"/></label></div><Button v-if="m.action" block @click="run('action')">{{m.action}}</Button>    <div v-if="m.kind==='sound'" class="audio-tools"><div class="actions"><Button :disabled="m.mode==='hearing'" type="primary" @click="run('listen')">{{m.mode==='echo'?'听原声与回声':'试听 6 秒'}}</Button><Button v-if="['loudness','pitch','timbre'].includes(m.mode)" @click="run('listen',true)">A/B 试听</Button><Button @click="run('stop')">停止声音</Button></div><label>试听音量 {{m.volume}}%<Slider :model-value="m.volume" :min="0" :max="100" :step="1" aria-label="试听音量" @update:model-value="run('change','volume',$event)"/></label><p role="status">{{m.audioStatus}}</p></div></section>
   <section v-if="m.kind==='sound'" class="wave-card"><h2>{{m.mode==='medium'?'传播速度 · 与空气同时出发':'接收位置的波形'}}</h2><p>{{m.mode==='medium'?'纵向：幅度示意 · 横向：传播距离':'纵向：相对幅度 · 横向：时间'}}</p><div v-if="m.mode==='medium'" class="actions"><span>红点：当前介质　灰环：空气基准</span><Button @click="run('restartPropagation')">重新同时出发</Button></div><svg viewBox="0 0 800 130" role="img" :aria-label="m.mode==='medium'?'相同距离下的声速对比':'声音的时间波形示意'"><path d="M35 65H780" stroke="#426372" stroke-dasharray="5 5"/><path :d="m.wavePath" fill="none" stroke="#60e3e7" stroke-width="3"/><template v-if="m.mode==='medium'"><circle v-for="point in marker.filter(p=>p.show)" :key="point.name" :cx="point.x" :cy="point.y" r="7" :fill="point.name==='空气基准'?'none':point.color" :stroke="point.color" stroke-width="3"/></template></svg><p v-if="m.mode==='medium'" role="status">{{m.propagation.status}}</p><p>{{m.waveNote}}</p></section>
   <section class="stats"><div class="stat" v-for="(stat,i) in m.stats" :key="i"><span>{{stat[0]}}</span><strong>{{stat[1]}}</strong><small>{{stat[2]}}</small></div></section>
   <section class="conclusion"><h3>这组条件告诉我们</h3><p>{{m.conclusion}}</p><p>{{m.note}}</p></section>
   <Collapse v-model="opened"><CollapseItem title="理解与实验步骤" name="concept"><p>{{m.current.review}}</p><div v-if="m.kind==='sound'" v-html="m.explanation"/><template v-else><ol><li v-for="step in m.current.steps" :key="step">{{step}}</li></ol><p>容易踩的坑：{{m.current.pitfall}}</p><p>{{m.current.source}}</p></template></CollapseItem><CollapseItem v-if="m.kind==='explore'" title="本页实验记录" name="records"><p>只保留当前页面最近6组，刷新后清空。</p><ol><li v-for="(record,i) in m.records" :key="i">{{record}}</li></ol><Button @click="run('clear')">清空本实验记录</Button></CollapseItem></Collapse>
   <section v-if="m.quiz" class="quiz"><div class="quiz-title"><h2>本实验小测</h2><Button class="close" icon="cross" aria-label="关闭小测验" @click="run('quiz',false)"/></div><h3>{{m.question.prompt}}</h3><div class="answers"><Button v-for="(option,i) in m.question.options" :key="i" @click="run('answer',i)">{{'ABCD'[i]}}. {{option}}</Button></div><p role="status">{{m.feedback}}</p></section><Button v-else block @click="run('quiz',true)">展开小测验</Button>
  </article>
 </div>
 <Popup :show="m.about" round closeable close-icon="cross" :style="{width:'min(92vw,600px)',padding:'30px'}" @update:show="run('about',$event)"><template v-if="m.kind==='explore'"><h2>动手，让物理看得见</h2><p>按苏科版2025年第4版八上第2—5章制作，共32个交互实验。光路、粒子与运动均为教学模型，适用条件显示在实验下方；公式推导与定量关系用于核对模型，不代替真实测量。</p><p>图示无需联网，不调用AI、不使用麦克风，也不改变学习记录或奖励。实验记录只保留在当前页面，刷新即清空。请在微课中继续完成复述与应用。</p></template><template v-else><h2>可以听见的物理</h2><p>本实验室用浏览器合成声音，将振幅、频率、音色与波形联系起来。合成音色是模型，不是实录乐器。</p><p>响度受到振幅、距离、频率及听觉等多种因素影响。距离实验采用理想自由声场的简化关系，真实教室中的反射、吸收和设备特性会影响结果。相对电平不是手机所在位置的实际分贝。</p><p>3D组件可用时支持拖动旋转、滚轮或双指缩放；离线或不支持3D时仍可使用图示与全部试听实验。本页不使用麦克风，也不上传声音。</p></template></Popup>
 <Popup :show="!!picker" position="bottom" round @update:show="!$event&&(picker=null)"><Picker :columns="choices" :model-value="[picker==='chapter'?m.chapter.id:m.state[picker]]" @confirm="confirm" @cancel="picker=null"><template #cancel><span class="cross" aria-label="关闭">×</span></template></Picker></Popup>
</main>
</template>
<style scoped>
