e{margin-bottom:16px;gap:8px}.control-title>div{gap:6px}.control-title label{font-weight:600}.physics-labs :deep(.van-slider){margin:16px 8px;width:calc(100% - 16px)}.physics-labs :deep(.van-slider__button-wrapper){padding:10px}.physics-labs :deep(.van-stepper__plus),.physics-labs :deep(.van-stepper__minus){width:44px;height:44px}.physics-labs :deep(.van-stepper__input){width:58px;height:44px;font-size:16px}.toggle{gap:16px}.audio-tools{border-top:1px solid #dde5dd;margin-top:20px;padding-top:8px}.audio-tools label{display:block;margin-top:20px}.wave-card svg{width:100%;background:#102d3b;border-radius:8px}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:22px 0}.stats>div{border:1px solid #dbe4dc;padding:16px;border-radius:12px;background:#f2f6f2}.stats span,.stats strong,.stats small{display:block;overflow-wrap:anywhere}.stats strong{font-size:22px}.stats small{color:#69786d}.conclusion{padding:8px 0 24px}.quiz{margin-top:22px}.answers{display:grid;gap:12px}.answers :deep(.van-button__text){text-align:left;width:100%}.close{min-width:44px!important;min-height:44px!important;padding:0!important}.physics-labs :deep(.van-popup__close-icon){top:4px;right:4px;min-width:44px;min-height:44px;display:grid;place-items:center}.cross{font-size:26px;display:grid;place-items:center;min-width:44px;min-height:44px}.physics-labs a:focus-visible{outline:3px solid #22634b;outline-offset:3px}@media(max-width:800px){.lab-layout{grid-template-columns:minmax(0,1fr);gap:18px}.topics{display:flex;flex-direction:row;overflow:auto;padding-bottom:10px;max-width:100%}.topics :deep(.van-button){min-width:180px;flex:0 0 auto;max-width:230px}.stats{grid-template-columns:1fr}.stats>div{padding:14px}.control-title{align-items:start}.scene-host{height:260px}.physics-labs .top{align-items:start}.top>div{gap:8px}}

